// DispatchControlsSchema returns the schema of dispatch_controls.
func DispatchControlsSchema() *schema.Table { return &dispatchControlsTable }

// As returns a handle that references dispatch_controls under its own alias.
func (t *DispatchControlsTable) As(alias string) *DispatchControlsTable {
	return keel.Alias(t.Ref, alias, BuildDispatchControls)
}

// Get returns the dispatch_controls row with the given key, or keel.ErrNotFound.
func (t *DispatchControlsTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*dispatchcontrol.DispatchControl, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newDispatchControl() unsafe.Pointer { return unsafe.Pointer(new(dispatchcontrol.DispatchControl)) }

func newNDispatchControl(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]dispatchcontrol.DispatchControl, n)))
}

